test('corps : showToast conserve incidents, classe critique, minuterie et toutes les autres fonctions du core',()=>{const before=parse(at(proof.baseCommit,'plateau-core.js')),after=parse(at(proof.codeCommit,'plateau-core.js')),fn=t=>t.body.find(n=>n.type==='FunctionDeclaration'&&n.id.name==='showToast'),a=fn(before),b=fn(after);function clean(n){n=strip(n);n.params=n.params.filter(p=>p.name!=='presentation');n.body.body=n.body.body.filter(x=>{if(x.type==='VariableDeclaration'&&['corpsJoueur','sub'].includes(x.declarations[0].id.name))return false;if(x.type==='IfStatement'&&x.test.type==='MemberExpression'&&x.test.object.name==='sub'&&x.test.property.name==='dataset')return false;if(x.type==='ExpressionStatement'){const left=x.expression.left;if(left?.object?.name==='sub')return false;if(left?.property?.name==='textContent'&&left.object?.type==='CallExpression'&&left.object.arguments[0]?.value==='toast-sub')return false;}return true;});return n;}assert.deepEqual(clean(a),clean(b));for(const t of [before,after])t.body=t.body.filter(n=>n!==fn(t));assert.deepEqual(strip(after),strip(before));});
